pub fn packages() -> Vec<String> {
    LICENSES.with(|licenses| {
        let mut packages = Vec::<String>::new();
        for entry in licenses.borrow().iter() {
            for package in &entry.packages {
                if !packages.contains(package) {
                    packages.push(package.clone());
                }
            }
        }
        packages
    })
}
